/**
 * Weekly USD price series for BTC, ETH and SOL. GENERATED FILE - do not edit by hand.
 *
 * One point per Monday (UTC), plus the most recent day available.
 *
 * Sources:
 *  - Coin Metrics Community Network Data (github.com/coinmetrics/data, csv/<asset>.csv),
 *    daily `PriceUSD` (BTC, ETH) / `ReferenceRateUSD` (SOL) - the UTC daily close.
 *    Used for every point up to and including `coinMetricsThrough`.
 *  - After that date: CoinGecko USD spot prices captured once a day (roughly 12:00-18:00 UTC)
 *    and committed to github.com/IQUXAe/daily-crypto-commit (crypto_prices_YYYYMMDD.json).
 *    Where the two overlapped (Mar-May 2026) they agreed within about 1% on most weeks and
 *    within 7% on the worst week, the gap being intraday vs. daily-close timing.
 *  - Coin Metrics' community file carries no SOL price before 2026-05-18, so the SOL series
 *    starts with the first CoinGecko snapshot (2025-12-01). Earlier SOL history is not bundled.
 *
 * Regenerate by re-running the same pipeline (see src/data/priceHistory/index.ts).
 */

export type PriceHistoryAssetId = 'bitcoin' | 'ethereum' | 'solana';

export interface WeeklySeries {
  /** Last date whose price comes from Coin Metrics (later points are CoinGecko snapshots). */
  coinMetricsThrough: string | null;
  /** [ISO date, USD price] pairs, ascending. */
  points: ReadonlyArray<readonly [string, number]>;
}

